const PRIORITY = ['low', 'normal', 'high'];
let nextId = 1;

export async function listTools() {
  return [
    {
      name: 'ticket_create',
      description: 'Create a support ticket.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', minLength: 1 },
          description: { type: 'string', minLength: 1 },
          priority: { type: 'string', enum: PRIORITY, default: 'normal' }
        },
        required: ['title', 'description'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { title, description, priority = 'normal' } = args || {};
  if (typeof title !== 'string' || title.trim().length === 0) {
    throw new Error('title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.trim().length === 0) {
    throw new Error('description must be a non-empty string');
  }
  if (!PRIORITY.includes(priority)) {
    throw new Error('priority must be one of low, normal, high');
  }
  // no extra fields
  const allowed = ['title', 'description', 'priority'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  const id = `t${nextId++}`;
  const text = `Created ticket ${id}: ${title} (priority: ${priority})`;
  return { content: [{ type: 'text', text }] };
}
